        int h = item / W, b = item % W;
        mm.SetTensorA(qg[(h * S + row0 + b * M) * D]);
        mm.SetTensorB(kg[(h / (HQ / HK)) * S * D], true);
        mm.IterateAll(sg[(h * WM + b * M) * n]);
        mm.End();
    }
}
