                                            (uint8_t*)probs.data_ptr(), row0, n);
        pv<<<CORES, nullptr, stream>>>((uint8_t*)probs.data_ptr(), (uint8_t*)vt.data_ptr(),
                                     (uint8_t*)result.data_ptr(), n);
        scatter<<<VCORES, nullptr, stream>>>((uint8_t*)result.data_ptr(),
                                            (uint8_t*)output.data_ptr(), row0);
    }
}

